    assert_eq!(capture["provider_execution"], false);
    assert_eq!(capture["request"]["body"]["reasoning"]["effort"], "high");
    assert!(capture["request"]["headers"].get("authorization").is_none());
    println!("{}", String::from_utf8_lossy(&out.stdout));
