   201	        entries.extend(tiers);
   202	    }
   203	    for cost in entries {
   204	        for key in ["input", "cacheRead", "cacheWrite"] {
   205	            let value = cost[key]
   206	                .as_f64()
   207	                .filter(|v| v.is_finite() && *v >= 0.0 && *v <= 1000.0)
